import { INVOICE_STATUS } from './constants.mjs';
import { computeGraduatedCharge } from './tierEngine.mjs';
import { applyCredits } from './creditPool.mjs';
import { encodeFrozenWireDigest } from './frozenWire.mjs';

/**
 * Builds an invoice from usage rows and credit grants.
 *
 * @param {object} params
 * @returns {object}
 */
export function buildInvoice({
  invoiceId,
  accountId,
  currency = 'USD',
  usageRows = [],
  grants = [],
  asOfMs = 0
} = {}) {
  const lineItems = [];
  let usageSubtotalCents = 0;

  for (const row of usageRows) {
    const { totalCents } = computeGraduatedCharge(row.units, row.tiers);
    usageSubtotalCents += totalCents;
    lineItems.push({
      metric: row.metric,
      units: row.units,
      amountCents: totalCents
    });
  }

  const creditResult = applyCredits(usageSubtotalCents, grants, asOfMs);
  const totalDueCents = creditResult.remainingChargeCents;
  const status = INVOICE_STATUS.FINALIZED;
  const wireDigest = encodeFrozenWireDigest({
    invoiceId,
    accountId,
    currency,
    totalDueCents,
    status
  });

  return {
    invoiceId,
    accountId,
    currency,
    status,
    lineItems,
    usageSubtotalCents,
    appliedCreditsCents: creditResult.appliedCents,
    creditAllocations: creditResult.allocations,
    totalDueCents,
    wireDigest
  };
}
import { ERROR_CODES, LedgerError } from './errors.mjs';

/**
 * Applies available credit grants to a positive charge amount in cents.
 *
 * @param {number} chargeCents
 * @param {Array<{ grantId: string, remainingCents: number, effectiveFromMs: number, expiresAtMs: number }>} grants
 * @param {number} asOfMs
 * @returns {{ appliedCents: number, remainingChargeCents: number, allocations: Array<{ grantId: string, appliedCents: number }>, updatedGrants: Array<object> }}
 */
export function applyCredits(chargeCents, grants = [], asOfMs = 0) {
  if (!Number.isFinite(chargeCents)) {
    throw new LedgerError(ERROR_CODES.ERR_INVALID_AMOUNT, 'chargeCents must be finite');
  }
  if (!Array.isArray(grants)) {
    throw new LedgerError(ERROR_CODES.ERR_INVALID_CONFIG, 'grants must be an array');
  }

  let remaining = chargeCents;
  let appliedCents = 0;
  const allocations = [];

  for (const grant of grants) {
    if (remaining <= 0) break;
    if (!grant || grant.remainingCents <= 0) continue;
    const take = Math.min(remaining, grant.remainingCents);
    grant.remainingCents -= take;
    remaining -= take;
    appliedCents += take;
    allocations.push({ grantId: grant.grantId, appliedCents: take });
  }

  return {
    appliedCents,
    remainingChargeCents: remaining,
    allocations,
    updatedGrants: grants
  };
}

/**
 * Summarizes total remaining cents across credit grants.
 *
 * @param {Array<{ remainingCents: number, effectiveFromMs: number, expiresAtMs: number }>} grants
 * @param {number} asOfMs
 */
export function summarizePoolBalance(grants = [], asOfMs = 0) {
  let availableCents = 0;
  let activeCount = 0;
  for (const g of grants) {
    if (g && g.remainingCents > 0) {
      availableCents += g.remainingCents;
      activeCount += 1;
    }
  }
  return { availableCents, activeCount, asOfMs };
}
import { ERROR_CODES, LedgerError } from './errors.mjs';

/**
 * Computes graduated (marginal/tiered) usage charges.
 *
 * @param {number} units
 * @param {Array<{ upTo: number | null, unitRateCents: number }>} tiers
 * @returns {{ totalCents: number, breakdown: Array<{ tierIndex: number, upTo: number | null, units: number, unitRateCents: number, subtotalCents: number }> }}
 */
export function computeGraduatedCharge(units, tiers) {
  if (!Array.isArray(tiers) || tiers.length === 0) {
    throw new LedgerError(ERROR_CODES.ERR_INVALID_TIERS, 'tiers must be a non-empty array');
  }
  if (!Number.isFinite(units) || units < 0) {
    return { totalCents: 0, breakdown: [] };
  }

  let prevUpTo = 0;
  let totalCents = 0;
  const breakdown = [];

  for (let i = 0; i < tiers.length; i += 1) {
    const tier = tiers[i];
    const cap = tier.upTo === null || tier.upTo === undefined || tier.upTo === Infinity ? Infinity : tier.upTo;
    if (units <= prevUpTo && i > 0) break;

    const bounded = Math.min(units, cap);
    const bandUnits = Math.max(0, bounded - prevUpTo + (prevUpTo > 0 ? 1 : 0));
    const subtotalCents = Math.floor(bandUnits * tier.unitRateCents);
    totalCents += subtotalCents;
    breakdown.push({
      tierIndex: i,
      upTo: cap === Infinity ? null : cap,
      units: bandUnits,
      unitRateCents: tier.unitRateCents,
      subtotalCents
    });
    if (cap === Infinity) break;
    prevUpTo = cap;
  }

  return { totalCents, breakdown };
}

/**
 * Computes volume (all-units-at-matched-tier-rate) usage charges.
 *
 * @param {number} units
 * @param {Array<{ upTo: number | null, unitRateCents: number }>} tiers
 * @returns {{ totalCents: number, matchedTierIndex: number, unitRateCents: number }}
 */
export function computeVolumeCharge(units, tiers) {
  if (!Array.isArray(tiers) || tiers.length === 0) {
    throw new LedgerError(ERROR_CODES.ERR_INVALID_TIERS, 'tiers must be a non-empty array');
  }
  if (!Number.isFinite(units) || units < 0) {
    throw new LedgerError(ERROR_CODES.ERR_NEGATIVE_UNITS, 'units must be >= 0');
  }
  if (units === 0) {
    return { totalCents: 0, matchedTierIndex: 0, unitRateCents: tiers[0].unitRateCents };
  }

  for (let i = 0; i < tiers.length; i += 1) {
    const cap = tiers[i].upTo === null || tiers[i].upTo === undefined ? Infinity : tiers[i].upTo;
    if (units <= cap) {
      return {
        totalCents: Math.round(units * tiers[i].unitRateCents),
        matchedTierIndex: i,
        unitRateCents: tiers[i].unitRateCents
      };
    }
  }
  const lastIdx = tiers.length - 1;
  return {
    totalCents: Math.round(units * tiers[lastIdx].unitRateCents),
    matchedTierIndex: lastIdx,
    unitRateCents: tiers[lastIdx].unitRateCents
  };
}
export const SUPPORTED_CURRENCIES = Object.freeze(['USD', 'EUR', 'GBP']);

export const INVOICE_STATUS = Object.freeze({
  DRAFT: 'DRAFT',
  FINALIZED: 'FINALIZED',
  VOIDED: 'VOIDED'
});

export const ROUNDING_MODES = Object.freeze({
  HALF_AWAY_FROM_ZERO: 'HALF_AWAY_FROM_ZERO',
  FLOOR: 'FLOOR'
});

export const MAX_BPS = 10_000;
export const WIRE_SCHEMA_VERSION = 'LP-WIRE-V1';
export const DEFAULT_TIME_ZONE = 'UTC';
export const ERROR_CODES = Object.freeze({
  ERR_NEGATIVE_UNITS: 'ERR_NEGATIVE_UNITS',
  ERR_INVALID_TIERS: 'ERR_INVALID_TIERS',
  ERR_INVALID_AMOUNT: 'ERR_INVALID_AMOUNT',
  ERR_IDEMPOTENCY_CONFLICT: 'ERR_IDEMPOTENCY_CONFLICT',
  ERR_INVALID_TTL: 'ERR_INVALID_TTL',
  ERR_INVALID_CONFIG: 'ERR_INVALID_CONFIG',
  ERR_DSL_SYNTAX: 'ERR_DSL_SYNTAX',
  ERR_INVALID_TIMEZONE: 'ERR_INVALID_TIMEZONE',
  ERR_SINK_FAILURE: 'ERR_SINK_FAILURE',
  ERR_INVALID_EVENT: 'ERR_INVALID_EVENT'
});

export class LedgerError extends Error {
  /**
   * @param {string} code
   * @param {string} message
   * @param {object} [details]
   */
  constructor(code, message, details = undefined) {
    super(message);
    this.name = 'LedgerError';
    this.code = code;
    if (details !== undefined) {
      this.details = details;
    }
  }
}
import test from 'node:test';
import assert from 'node:assert/strict';
import { buildInvoice } from '../src/invoiceBuilder.mjs';
import { encodeFrozenWireDigest } from '../src/frozenWire.mjs';

test('buildInvoice computes subtotal, credits, totalDue, and frozen wire digest', () => {
  const tiers = [
    { upTo: 100, unitRateCents: 10 },
    { upTo: null, unitRateCents: 5 }
  ];
  const inv = buildInvoice({
    invoiceId: 'inv-100',
    accountId: 'acct-alpha',
    currency: 'USD',
    usageRows: [{ metric: 'api_calls', units: 60, tiers }],
    grants: [{ grantId: 'g1', remainingCents: 200, effectiveFromMs: 0, expiresAtMs: 99_999 }],
    asOfMs: 5000
  });
  assert.equal(inv.usageSubtotalCents, 600);
  assert.equal(inv.appliedCreditsCents, 200);
  assert.equal(inv.totalDueCents, 400);
  assert.equal(
    inv.wireDigest,
    encodeFrozenWireDigest({
      invoiceId: 'inv-100',
      accountId: 'acct-alpha',
      currency: 'USD',
      totalDueCents: 400,
      status: 'FINALIZED'
    })
  );
});
import test from 'node:test';
import assert from 'node:assert/strict';
import { compileFilter } from '../src/queryDsl.mjs';
import { getBillingWindowBounds, enumerateDailyWindows } from '../src/clock.mjs';

test('queryDsl compiles basic comparisons and AND', () => {
  const pred = compileFilter('status == "ok" AND count >= 10');
  assert.equal(pred({ status: 'ok', count: 12 }), true);
  assert.equal(pred({ status: 'ok', count: 5 }), false);
  assert.equal(pred({ status: 'err', count: 12 }), false);
});

test('clock computes UTC and winter New York windows', () => {
  const utcWin = getBillingWindowBounds(Date.UTC(2026, 0, 15, 14, 30, 0), 'UTC', 0);
  assert.equal(utcWin.localDate, '2026-01-15');
  assert.equal(utcWin.startUtcMs, Date.UTC(2026, 0, 15, 0, 0, 0));
  assert.equal(utcWin.endUtcMs, Date.UTC(2026, 0, 16, 0, 0, 0));

  const nyWin = getBillingWindowBounds(Date.UTC(2026, 0, 15, 15, 0, 0), 'America/New_York', 0);
  assert.equal(nyWin.localDate, '2026-01-15');
  assert.equal(nyWin.startUtcMs, Date.UTC(2026, 0, 15, 5, 0, 0));

  const list = enumerateDailyWindows(Date.UTC(2026, 0, 15, 0, 0, 0), Date.UTC(2026, 0, 17, 0, 0, 0), 'UTC', 0);
  assert.equal(list.length, 2);
});
