import { DEFAULT_TIME_ZONE } from './constants.mjs';
import { ERROR_CODES, LedgerError } from './errors.mjs';

const DAY_MS = 86_400_000;

const formatterCache = new Map();

function getFormatter(timeZone) {
  let fmt = formatterCache.get(timeZone);
  if (fmt) return fmt;
  try {
    fmt = new Intl.DateTimeFormat('en-CA', {
      timeZone,
      hourCycle: 'h23',
      year: 'numeric',
      month: '2-digit',
      day: '2-digit',
      hour: '2-digit',
      minute: '2-digit',
      second: '2-digit'
    });
  } catch (err) {
    throw new LedgerError(ERROR_CODES.ERR_INVALID_TIMEZONE, `Invalid timeZone: ${timeZone}`, { cause: err.message });
  }
  formatterCache.set(timeZone, fmt);
  return fmt;
}

function extractLocalParts(utcMs, timeZone) {
  const parts = {};
  for (const p of getFormatter(timeZone).formatToParts(new Date(utcMs))) {
    if (p.type !== 'literal') {
      parts[p.type] = Number(p.value);
    }
  }
  // Some engines render midnight as hour 24 even with h23.
  if (parts.hour === 24) parts.hour = 0;
  return parts;
}

