 * @param {number} [anchorHourLocal=0]
 * @returns {Array<{ startUtcMs: number, endUtcMs: number, localDate: string, timeZone: string }>}
 */
export function enumerateDailyWindows(startUtcMs, endUtcMs, timeZone = DEFAULT_TIME_ZONE, anchorHourLocal = 0) {
  if (!Number.isFinite(startUtcMs) || !Number.isFinite(endUtcMs) || endUtcMs < startUtcMs) {
    throw new LedgerError(ERROR_CODES.ERR_INVALID_CONFIG, 'Invalid window range');
  }
  validateAnchorHour(anchorHourLocal);
  getFormatter(timeZone);
  if (startUtcMs === endUtcMs) return [];

  const windows = [];
  let { day, startUtcMs: wStart, endUtcMs: wEnd } = locateDay(startUtcMs, timeZone, anchorHourLocal);
  while (wStart < endUtcMs) {
    windows.push({ startUtcMs: wStart, endUtcMs: wEnd, localDate: formatDate(day), timeZone });
    day = addDays(day, 1);
    wStart = wEnd;
    const next = addDays(day, 1);
    wEnd = anchorUtcMs(next.year, next.month, next.day, timeZone, anchorHourLocal);
  }
  return windows;
}

