function compareCodeUnits(a, b) {
  if (a < b) return -1;
  if (a > b) return 1;
  return 0;
}

function isGrantActive(grant, asOfMs) {
  if (!grant || !(grant.remainingCents > 0)) return false;
  const from = Number.isFinite(grant.effectiveFromMs) ? grant.effectiveFromMs : -Infinity;
  const until = grant.expiresAtMs === null || grant.expiresAtMs === undefined ? Infinity : grant.expiresAtMs;
  return from <= asOfMs && asOfMs < until;
}

/**
 * Builds one invoice per local daily billing window intersecting
 * [rangeStartUtcMs, rangeEndUtcMs), carrying remaining credit balances
 * chronologically across windows. Inputs are never mutated.
 *
 * @param {object} params
 * @returns {Array<object>}
 */
export function buildDailyWindowInvoices({
  accountId,
  currency = 'USD',
  timeZone = 'UTC',
  anchorHourLocal = 0,
  rangeStartUtcMs,
  rangeEndUtcMs,
  events = [],
  metricTiers = {},
  grants = []
} = {}) {
  if (!Array.isArray(events)) {
    throw new LedgerError(ERROR_CODES.ERR_INVALID_CONFIG, 'events must be an array');
  }
  if (!Array.isArray(grants)) {
    throw new LedgerError(ERROR_CODES.ERR_INVALID_CONFIG, 'grants must be an array');
  }
  const windows = enumerateDailyWindows(rangeStartUtcMs, rangeEndUtcMs, timeZone, anchorHourLocal);
  const tiersByMetric = metricTiers || {};

  // Per-window metric -> units aggregation.
  const buckets = windows.map(() => new Map());
  for (const evt of events) {
    if (!evt || !Number.isFinite(evt.timestampMs)) continue;
    const ts = evt.timestampMs;
    if (ts < rangeStartUtcMs || ts >= rangeEndUtcMs) continue;
    let lo = 0;
    let hi = windows.length - 1;
    let idx = -1;
    while (lo <= hi) {
      const mid = (lo + hi) >> 1;
      const w = windows[mid];
      if (ts < w.startUtcMs) hi = mid - 1;
      else if (ts >= w.endUtcMs) lo = mid + 1;
      else {
        idx = mid;
        break;
      }
    }
    if (idx === -1) continue;
    const units = Number.isFinite(evt.units) ? evt.units : 0;
    const bucket = buckets[idx];
    bucket.set(evt.metric, (bucket.get(evt.metric) ?? 0) + units);
  }

  const pool = grants.map((g) => (g && typeof g === 'object' ? { ...g } : g));
  const invoices = [];
  for (let i = 0; i < windows.length; i += 1) {
    const w = windows[i];
    const usageRows = [...buckets[i].entries()]
      .sort((a, b) => compareCodeUnits(a[0], b[0]))
      .map(([metric, units]) => ({ metric, units, tiers: tiersByMetric[metric] }));
    const activeGrants = pool.filter((g) => isGrantActive(g, w.startUtcMs));
    invoices.push(
      buildInvoice({
        invoiceId: `${accountId}:${w.localDate}`,
        accountId,
        currency,
        usageRows,
        grants: activeGrants,
        asOfMs: w.startUtcMs
      })
    );
  }
  return invoices;
}
